function minimumOperations(nums) {
  // For each element, try moving it further and further in both directions until it lands on a multiple of 3.
  let total = 0;
  for (const value of nums) {
    let steps = 0;
    while ((value + steps) % 3 !== 0 && (value - steps) % 3 !== 0) steps++;
    total += steps;
  }
  return total;
}

