function generate(rand, size) {
  const n = size === 'large' ? 50 : 1 + Math.floor(rand() * 8);
  const mode = rand();
  const nums = Array.from({ length: n }, () => {
    if (mode < 0.2) return 3 * (1 + Math.floor(rand() * 16));
    return 1 + Math.floor(rand() * 50);
  });
  return [nums];
}
